from pwn import *
import itertools

def test_sequence(sequence):
    p = remote('pwn.chal.csaw.io', 8000)
    result = b''

    try:
        for num in sequence:
            p.sendline(str(num).encode())
            try:
                output = p.recvuntil(b':', timeout=0.5)
                result += output
            except:
                pass

        final = p.recvall(timeout=1)
        result += final
    except:
        pass
    finally:
        p.close()

    return result

# Test sequences of length 8 (same as the array length)
def generate_sequences(length=8):
    return itertools.product([1, 2], repeat=length)

print("Testing systematic sequences...")
for seq in generate_sequences(8):
    if b"secret" not in result:  # Only print if we found something interesting
        print(f"\nTesting sequence: {seq}")
        result = test_sequence(seq)
        if b"secret" in result or b"flag" in result:
            print(f"Found interesting result with sequence {seq}:")
            print(result)
            break

