#!/usr/bin/env python3
from pwn import *
import time

def test_sequence(sequence):
    try:
        p = remote('pwn.chal.csaw.io', 8000, timeout=5)
        time.sleep(1)  # Wait for initial prompt
        result = p.recvuntil(b'enter a number', timeout=5)
        print(f"Initial prompt: {result}")

        for num in sequence:
            print(f"Sending: {num}")
            p.sendline(str(num).encode())
            time.sleep(0.5)
            try:
                result = p.recvuntil(b'enter a number', timeout=5)
                print(f"Received: {result}")
            except EOFError:
                print("Connection closed by remote host")
                break
            except Exception as e:
                print(f"Error receiving: {e}")
                break

        p.close()
    except Exception as e:
        print(f"Error in sequence: {e}")

sequences = [
    [1,1,1,2,2,1],
    [1,2,1,2,1,2],
    [2,2,2,1,1,2]
]

for seq in sequences:
    print(f"\nTesting sequence: {seq}")
    test_sequence(seq)

