#!/usr/bin/env python3
from pwn import *
import time
import sys

def connect():
    return remote('pwn.chal.csaw.io', 8000)

def send_sequence(conn, sequence):
    result = []
    for num in sequence:
        conn.sendline(str(num).encode())
        time.sleep(0.1)  # Small delay to ensure proper order
        try:
            resp = conn.recvuntil(b'Enter choice:', timeout=1)
            result.append(resp)
        except EOFError:
            result.append(b'EOFError')
            break
    return result

def test_sequence(sequence, desc):
    print(f"\nTesting sequence: {sequence}")
    print(f"Description: {desc}")
    conn = connect()
    initial = conn.recvuntil(b'Enter choice:')
    print("Initial banner:", initial)

    results = send_sequence(conn, sequence)

    print("\nResponses:")
    for i, resp in enumerate(results):
        print(f"After input {sequence[i]}:")
        print(hexdump(resp))

    try:
        conn.close()
    except:
        pass

sequences = [
    ([1, 2], "Basic complementary operations"),
    ([1, 1, 1], "Triple A operations"),
    ([2, 2, 2], "Triple B operations"),
    ([1,2,1,2,1,2,1,2,1,2], "Alternating A-B long sequence"),
    ([2,1,2,1,2,1,2,1,2,1], "Alternating B-A long sequence"),
]

for seq, desc in sequences:
    test_sequence(seq, desc)
    time.sleep(1)  # Delay between tests

