from pwn import *

def try_sequence(p, sequence):
    for move in sequence:
        p.sendline(bytes(str(move), 'utf-8'))
        resp = p.recvline()
        if b'secret' in resp.lower():
            log.success(f"Found secret with sequence: {sequence}")
            return True
    return False

def main():
    # Initial buffer: DE AD BE EF CA FE BA BE

    # Try all possible combinations of rotations up to length 8
    for length in range(1, 9):
        for combination in range(2**length):
            sequence = []
            for i in range(length):
                # Convert each bit to 1 or 2 (left or right rotation)
                if (combination >> i) & 1:
                    sequence.append(1)
                else:
                    sequence.append(2)

            p = remote('pwn.chal.csaw.io', 8000)
            log.info(f"Trying sequence: {sequence}")
            if try_sequence(p, sequence):
                p.interactive()
                return
            p.close()

if __name__ == '__main__':
    main()

